function reviewedInputBytes(file){let value=Buffer.from(historicalSource(file,reviewedCreationScopeInput(file,reviewedMigrationRepairInput(file,readFileSync(new URL('../../../'+file,import.meta.url),'utf8')))));if(file==='services/pg-api/src/pg18-complete-profile-source.mjs'&&sha(value)==='1de843ca839bcc3cbc280cc3137d7c0857d964c88d702a81ba9903d57c44ec52'){let text=value.toString('utf8');for(const h of [...composedSourceInverse].reverse()){assert.equal(text.split(h.after).length,2);text=text.replace(h.after,()=>h.before)}value=Buffer.from(text)}return value}
