function subject({omit=null,corrupt=null,execFail=null}={}){const trace=[],marker=Error('fixed inert exec refusal'),manifest=pinRows.filter(p=>p.path!==omit),blobs=new Map([...data].map(([p,b])=>[path.join('/fixed-source-root',p),corrupt===p?Buffer.concat([b,Buffer.from('\n')]):b]));let active=0,maxActive=0;const f={db:{async exec(sql){active++;maxActive=Math.max(maxActive,active);try{const p=pinRows.find(p=>data.get(p.path).toString('utf8')===sql);assert(p);trace.push(p.path);await Promise.resolve();if(p.path===execFail)throw marker}finally{active--}}}};const api=vm.runInNewContext('const readPin='+readPin.getText(tree)+';async function run(){'+loop.getText(tree)+'};run',{assert,sha,path,repo:'/fixed-source-root',fs:{async readFile(p){assert(blobs.has(p));return blobs.get(p)}},snapshot:{manifest:{sql_sources:manifest}},f},{timeout:1000});return{run:api,trace,marker,max:()=>maxActive}}
