for(const row of fixed.added_SQL){test('missing '+row.version+' pin refuses before its inert exec',async()=>{const o=subject({omit:row.path});await assert.rejects(o.run());assert.equal(o.trace.length,expectedVersions.indexOf(row.version));assert.equal(o.trace.includes(row.path),false);assert.equal(o.trace.includes(pinRows.at(-1).path),false)});test('changed '+row.version+' SQL bytes refuse before its inert exec',async()=>{const o=subject({corrupt:row.path});await assert.rejects(o.run());assert.equal(o.trace.length,expectedVersions.indexOf(row.version));assert.equal(o.trace.includes(row.path),false);assert.equal(o.trace.includes(pinRows.at(-1).path),false)});test('original '+row.version+' exec error propagates and stops later migration',async()=>{const o=subject({execFail:row.path});await assert.rejects(o.run(),e=>e===o.marker);assert.equal(o.trace.at(-1),row.path);assert.equal(o.trace.includes(pinRows.at(-1).path),false)})}
